#{filePath}
AND c.chunk_version = #{chunkVersion} AND c.use_yn = 'Y'

UPDATE rag_documents SET use_yn = 'N', imported_at = NOW() WHERE file_path IN
#{filePath}
AND use_yn = 'Y'

mapper.select:
SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, CASE WHEN doc.document_type = 'official_doc' THEN '공식 가이드 문서' WHEN doc.document_type = 'internal_doc' THEN '내부 지침/매뉴얼' WHEN doc.document_type = 'reference_doc' THEN '참고자료' ELSE doc.document_type END AS categoryName, doc.published_date AS sourceDate, NULL AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, c.parent_section_title AS parentSectionTitle, c.section_type AS sectionType FROM rag_document_chunks c JOIN rag_documents doc ON doc.document_id = c.document_id WHERE c.chunk_id IN
#{chunkId}
AND doc.use_yn = 'Y' AND c.use_yn = 'Y' AND

SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, CASE WHEN doc.document_type = 'official_doc' THEN '공식 가이드 문서' WHEN doc.document_type = 'internal_doc' THEN '내부 지침/매뉴얼' WHEN doc.document_type = 'reference_doc' THEN '참고자료' ELSE doc.document_type END AS categoryName, doc.published_date AS sourceDate, NULL AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, c.parent_section_title AS parentSectionTitle, c.section_type AS sectionType FROM rag_document_chunks c JOIN rag_documents doc ON doc.document_id = c.document_id WHERE doc.use_yn = 'Y' AND c.use_yn = 'Y' AND
AND doc.document_type IN
#{documentType}
AND (
c.chunk_text LIKE CONCAT('%', #{keyword}, '%') OR c.chunk_title LIKE CONCAT('%', #{keyword}, '%') OR c.parent_section_title LIKE CONCAT('%', #{keyword}, '%') OR c.embedding_text LIKE CONCAT('%', #{keyword}, '%') OR doc.title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY doc.document_type, doc.title, c.sort_order LIMIT #{limit}

SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, CASE WHEN doc.document_type = 'official_doc' THEN '공식 가이드 문서' WHEN doc.document_type = 'internal_doc' THEN '내부 지침/매뉴얼' WHEN doc.document_type = 'reference_doc' THEN '참고자료' ELSE doc.document_type END AS categoryName, doc.published_date AS sourceDate, NULL AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, c.parent_section_title AS parentSectionTitle, c.section_type AS sectionType FROM rag_document_chunks c JOIN rag_documents doc ON doc.document_id = c.document_id WHERE doc.use_yn = 'Y' AND c.use_yn = 'Y' AND
AND doc.document_type IN
#{documentType}
AND (
doc.title LIKE CONCAT('%', #{keyword}, '%')
)
AND (
c.chunk_text LIKE CONCAT('%', #{keyword}, '%') OR c.chunk_title LIKE CONCAT('%', #{keyword}, '%') OR c.parent_section_title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY (
(CASE WHEN c.chunk_text LIKE CONCAT('%', #{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN c.chunk_title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END) + (CASE WHEN c.parent_section_title LIKE CONCAT('%', #{keyword}, '%') THEN 2 ELSE 0 END)
) DESC, (
(CASE WHEN doc.title = #{keyword} THEN 8 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT(#{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END)
) DESC, doc.document_type, doc.title, c.sort_order LIMIT #{limit}

WITH matched_docs AS ( SELECT doc.document_id, doc.document_type, doc.title, doc.source_org, doc.published_date, doc.source_url, doc.file_path FROM rag_documents doc WHERE doc.use_yn = 'Y'
AND doc.document_type IN
#{documentType}
AND (
doc.title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY (
(CASE WHEN doc.title = #{keyword} THEN 8 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT(#{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END)
) DESC, doc.document_type, doc.title LIMIT #{limit} ), latest_versions AS ( SELECT c2.document_id, MAX(c2.chunk_version) AS chunk_version FROM rag_document_chunks c2 JOIN matched_docs md ON md.document_id = c2.document_id WHERE c2.use_yn = 'Y' GROUP BY c2.document_id ) SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, doc.document_type AS categoryName, doc.published_date AS sourceDate, NULL AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, c.parent_section_title AS parentSectionTitle, c.section_type AS sectionType FROM matched_docs doc JOIN latest_versions latest ON latest.document_id = doc.document_id JOIN rag_document_chunks c ON c.document_id = doc.document_id AND c.chunk_version = latest.chunk_version WHERE c.use_yn = 'Y'
AND (
c.chunk_text LIKE CONCAT('%', #{keyword}, '%') OR c.chunk_title LIKE CONCAT('%', #{keyword}, '%') OR c.parent_section_title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY (
(CASE WHEN c.chunk_text LIKE CONCAT('%', #{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN c.chunk_title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END) + (CASE WHEN c.parent_section_title LIKE CONCAT('%', #{keyword}, '%') THEN 2 ELSE 0 END)
) DESC, doc.document_type, doc.title, c.sort_order LIMIT #{limit}

WITH matched_docs AS ( SELECT doc.document_id, doc.document_type, doc.title, doc.source_org, doc.published_date, doc.source_url, doc.file_path, (
(CASE WHEN doc.title = #{keyword} THEN 8 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT(#{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END)
) AS title_score FROM rag_documents doc WHERE doc.use_yn = 'Y'
AND doc.document_type IN
#{documentType}
AND (
doc.title LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY title_score DESC, doc.document_type, doc.title LIMIT 12 ), latest_versions AS ( SELECT c2.document_id, MAX(c2.chunk_version) AS chunk_version FROM rag_document_chunks c2 JOIN matched_docs md ON md.document_id = c2.document_id WHERE c2.use_yn = 'Y' GROUP BY c2.document_id ) SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, doc.document_type AS categoryName, doc.published_date AS sourceDate, NULL AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, c.parent_section_title AS parentSectionTitle, c.section_type AS sectionType FROM matched_docs doc JOIN latest_versions latest ON latest.document_id = doc.document_id JOIN rag_document_chunks c ON c.document_id = doc.document_id AND c.chunk_version = latest.chunk_version WHERE c.use_yn = 'Y' ORDER BY doc.title_score DESC, doc.document_type, doc.title, c.sort_order LIMIT #{limit}

WITH matched_docs AS ( SELECT doc.document_id, doc.document_type, doc.title, doc.source_org, doc.published_date, doc.source_url, doc.file_path, (
(CASE WHEN doc.title = #{keyword} THEN 8 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT(#{keyword}, '%') THEN 5 ELSE 0 END) + (CASE WHEN doc.title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END)
) AS title_score FROM rag_documents doc WHERE doc.use_yn = 'Y'
AND doc.document_type IN
#{documentType}
AND (
doc.title LIKE CONCAT('%', #{keyword}, '%')
) ORDER BY title_score DESC, doc.document_type, doc.title LIMIT 12 ), latest_versions AS ( SELECT c2.document_id, MAX(c2.chunk_version) AS chunk_version FROM rag_document_chunks c2 JOIN matched_docs md ON md.document_id = c2.document_id WHERE c2.use_yn = 'Y' GROUP BY c2.document_id ) SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, doc.document_type AS categoryName, doc.published_date AS sourceDate, NULL AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, c.parent_section_title AS parentSectionTitle, c.section_type AS sectionType FROM matched_docs doc JOIN latest_versions latest ON latest.document_id = doc.document_id JOIN rag_document_chunks c ON c.document_id = doc.document_id AND c.chunk_version = latest.chunk_version WHERE c.use_yn = 'Y' ORDER BY (
(CASE WHEN c.chunk_text LIKE CONCAT('%', #{keyword}, '%') THEN 6 ELSE 0 END) + (CASE WHEN c.chunk_title LIKE CONCAT('%', #{keyword}, '%') THEN 4 ELSE 0 END) + (CASE WHEN c.parent_section_title LIKE CONCAT('%', #{keyword}, '%') THEN 3 ELSE 0 END)
) DESC, doc.title_score DESC, doc.document_type, doc.title, c.sort_order LIMIT #{limit}

SELECT c.chunk_id AS chunkId, c.document_id AS documentId, doc.document_type AS target, CAST(doc.document_id AS CHAR) AS externalId, doc.title AS title, doc.source_org AS agencyName, CASE WHEN doc.document_type = 'official_doc' THEN '공식 가이드 문서' WHEN doc.document_type = 'internal_doc' THEN '내부 지침/매뉴얼' WHEN doc.document_type = 'reference_doc' THEN '참고자료' ELSE doc.document_type END AS categoryName, doc.published_date AS sourceDate, NULL AS effectiveStatus, c.chunk_no AS chunkNo, c.chunk_title AS chunkTitle, c.chunk_text AS chunkText, c.page_no AS pageNo, c.source_path AS sourcePath, COALESCE(c.source_url, doc.source_url, doc.file_path) AS sourceUrl, c.sort_order AS sortOrder, c.content_hash AS contentHash, c.parent_section_title AS parentSectionTitle, c.section_type AS sectionType FROM ( SELECT doc2.document_id FROM rag_documents doc2 WHERE doc2.use_yn = 'Y'
AND doc2.document_type IN
#{documentType}
AND (
doc2.title LIKE CONCAT('%', #{keyword}, '%') OR doc2.source_org LIKE CONCAT('%', #{keyword}, '%') OR doc2.document_category LIKE CONCAT('%', #{keyword}, '%') OR doc2.document_topic LIKE CONCAT('%', #{keyword}, '%')
)
ORDER BY doc2.document_type, doc2.title LIMIT 16 ) matched_doc JOIN rag_documents doc ON doc.document_id = matched_doc.document_id JOIN rag_document_chunks c ON c.document_id = doc.document_id WHERE c.use_yn = 'Y' AND ORDER BY doc.document_type, doc.title, c.sort_order LIMIT #{limit}
